import { test, expect } from '@playwright/test';

test.describe('HTTP Status Code Reporting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
  });

  test('should display correct status code message when clicking 200', async ({ page }) => {
    // Verify initial page loads
    await expect(page).toHaveURL(/status_codes/);
    const statusMessage = page.getByText('This page returned a 200 status code');
    await expect(statusMessage).not.toBeVisible();

    // Click the 200 link using getByRole
    const statusLink = page.getByRole('link', { name: '200' });
    await statusLink.click();

    // Verify navigation to the correct URL
    await expect(page).toHaveURL(/status_codes\/200/);

    // Verify the status message is displayed
    await expect(statusMessage).toBeVisible();
    await expect(statusMessage).toContainText('200 status code');

    // Verify the status code is displayed in the page
    const statusCodeDisplay = page.getByText('200');
    await expect(statusCodeDisplay).toBeVisible();

    // Verify the response time is displayed
    const responseTime = page.getByText(/Response time/);
    await expect(responseTime).toBeVisible();
  });

  test('should display correct status code message when clicking 404', async ({ page }) => {
    // Verify initial page loads
    await expect(page).toHaveURL(/status_codes/);

    // Click the 400 link using getByRole
    const statusLink = page.getByRole('link', { name: '400' });
    await statusLink.click();

    // Verify navigation to the correct URL
    await expect(page).toHaveURL(/status_codes\/400/);

    // Verify the status message is displayed
    const statusMessage = page.getByText('This page returned a 400 status code');
    await expect(statusMessage).toBeVisible();

    // Verify the status code is displayed in the page
    const statusCodeDisplay = page.getByText('400');
    await expect(statusCodeDisplay).toBeVisible();

    // Verify the response time is displayed
    const responseTime = page.getByText(/Response time/);
    await expect(responseTime).toBeVisible();

    // Navigate back to the main status codes page
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await expect(page).toHaveURL(/status_codes/);
  });
});
